import AppKit
import Foundation
import H3Engine

// The image side of a window (plans/IMAGE_PLAN.ja.md): its draft, the
// project's images - generated by the image engine (H3ImageEngine) or
// brought in from files - the preview, and handing an image to the video
// form.

extension GenerationViewModel {
    // MARK: Draft

    /// What project.json records as the kind: nothing while making videos,
    /// so a project that never left the video side is written as before.
    var storedGenerationKind: String? {
        generationKind == .video ? nil : generationKind.rawValue
    }

    /// The image side of the form; nil while it is untouched, so project.json
    /// gains nothing until images are used.
    func currentImageDraft() -> ImageDraft? {
        var draft = ImageDraft(prompt: imagePrompt, model: nil, size: imageSizeProfile.rawValue,
                               seedFixed: imageSeedFixed, seed: imageSeedText, count: imageCount)
        if !imageEditReferences.isEmpty {
            let folder = project?.url
            draft.references = imageEditReferences.map { path in
                folder.map { ProjectFiles.stored(path, in: $0) } ?? path
            }
        }
        return draft == .blank && lastSavedProjectFile?.imageDraft == nil ? nil : draft
    }

    /// `projectURL`: the project the draft's relative paths are in (the
    /// open one when nil).
    func applyImageDraft(_ draft: ImageDraft, projectURL: URL? = nil) {
        imagePrompt = draft.prompt
        if let profile = ImageSizeProfile(rawValue: draft.size) { imageSizeProfile = profile }
        imageSeedFixed = draft.seedFixed
        imageSeedText = draft.seed
        imageCount = draft.count.clamped(to: imageCountRange)
        let folder = projectURL ?? project?.url
        imageEditReferences = (draft.references ?? []).map { stored in
            folder.map { ProjectFiles.resolved(stored, in: $0) } ?? stored
        }
    }

    // MARK: Editing: reference pictures

    /// The label the prompt calls the n-th reference by (n from 1).
    static func pictureTag(_ number: Int) -> String { "<Picture \(number)>" }

    /// 参照画像を追加…: pictures to edit. Kept in the order given; copied
    /// into the project when the form is saved, like a video's inputs.
    func chooseImageEditReferences() {
        let paths = chooseFiles(allowedContentTypes: imageTypes)
        guard !paths.isEmpty else { return }
        addImageEditReferences(paths)
    }

    /// Adds the files as references (those already there stay once). The
    /// first reference of a form sets the size to its picture's shape.
    func addImageEditReferences(_ paths: [String]) {
        noteInputsChosen(paths)
        let wasEmpty = imageEditReferences.isEmpty
        for path in paths where !imageEditReferences.contains(path) {
            guard imageEditReferences.count < imageReferenceLimit else {
                projectMessage = String(localized: "参照画像は\(imageReferenceLimit)枚までです")
                break
            }
            imageEditReferences.append(path)
        }
        if wasEmpty, let first = imageEditReferences.first, let size = ImageMetadata.pixelSize(atPath: first) {
            imageSizeProfile = imageModelIsPH3 ? .matchingPH3(width: size.width, height: size.height)
                                               : .matching(width: size.width, height: size.height)
        }
    }

    /// 参照をすべて取り除く: back to making a picture from the prompt alone.
    func removeAllImageEditReferences() {
        imageEditReferences = []
    }

    func removeImageEditReference(at index: Int) {
        guard imageEditReferences.indices.contains(index) else { return }
        imageEditReferences.remove(at: index)
    }

    /// Moves a reference one place towards the front (-1) or the back (+1):
    /// the prompt's numbers follow the order.
    func moveImageEditReference(at index: Int, by offset: Int) {
        let target = index + offset
        guard imageEditReferences.indices.contains(index), imageEditReferences.indices.contains(target) else { return }
        imageEditReferences.swapAt(index, target)
    }

    /// Puts the n-th reference's label at the end of the image prompt.
    func appendPictureTag(_ number: Int) {
        let tag = Self.pictureTag(number)
        if imagePrompt.isEmpty || imagePrompt.hasSuffix(" ") || imagePrompt.hasSuffix("\n") {
            imagePrompt += tag
        } else {
            imagePrompt += " " + tag
        }
    }

    /// この画像を編集: the image form takes this image as its only
    /// reference, at the image's own size. The prompt is left to the user
    /// (what to change); an empty one gets a start that names the picture.
    func editImage(_ image: ProjectImage) {
        guard !isGenerating else { return }
        generationKind = .image
        imageEditReferences = []
        addImageEditReferences([image.url.path])
        if imagePrompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            imagePrompt = "Edit \(Self.pictureTag(1)). "
        }
        imageSeedFixed = false
    }

    /// 参照画像に追加（画像の編集）: one more reference for the image form.
    func addImageAsEditReference(_ image: ProjectImage) {
        generationKind = .image
        addImageEditReferences([image.url.path])
    }

    /// The latent to use for a reference instead of encoding the picture:
    /// the one kept beside an image the app generated, when the reference
    /// is used at the image's own size and its file is still the one
    /// generated (the record's hash - a picture retouched elsewhere is
    /// encoded as what it is now). nil otherwise.
    static func editLatent(forReference path: String, maxShortEdge: Int, ph3: Bool = false) -> String? {
        guard let size = ImageMetadata.pixelSize(atPath: path),
              let canvas = H3ImageEngine.referenceCanvas(width: size.width, height: size.height,
                                                         maxShortEdge: maxShortEdge, ph3: ph3),
              canvas.width == size.width, canvas.height == size.height,
              let latent = ProjectFiles.frameLatent(forImage: path, canvasWidth: Int32(canvas.width),
                                                    canvasHeight: Int32(canvas.height)),
              let record = ProjectFiles.imageRecord(forImageAt: path),
              let hash = try? FileHash.sha256(ofFile: path), hash == record.sha256 else { return nil }
        return latent
    }

    // MARK: Validation and summary

    /// Why an image cannot be generated now (shown under the prompt).
    var imageValidationMessage: String? {
        if isImportingImages { return String(localized: "画像を取り込んでいます…") }
        guard let model = library.activeImageModel else {
            return String(localized: "画像モデルがまだ追加されていません。手元の画像は「取り込む」でプロジェクトに入れられます")
        }
        if !FileManager.default.fileExists(atPath: model.path) {
            return String(localized: "画像モデル「\(model.name)」のフォルダが見つかりません")
        }
        if let installed = H3ImageModel.installed(at: model.path) {
            // The copy is deleted, or the choice recorded, when these end.
            switch H3ImageModelSetup.of(installed).phase {
            case .comparing, .reading:
                return String(localized: "画像モデル「\(model.name)」のテキストエンコーダを照合しています。終わってから生成してください")
            default:
                break
            }
        }
        switch SharedTextEncoder.reading(forImageModel: model.path, videoModelPaths: videoModelPaths) {
        case .missing:
            return String(localized: "画像モデル「\(model.name)」が読む、動画モデルのテキストエンコーダが見つかりません。動画モデルを置いたディスクがつながっているか確かめるか、動画モデルを導入してください")
        case .needsChoice:
            return String(localized: "画像モデル「\(model.name)」が読んでいた動画モデルのテキストエンコーダが見つかりません。ほかの動画モデルのものは、同じ内容と確かめられていないので、自動では切り替えません。モデル管理の画像モデルの「管理…」で、使うものを選んでください")
        case .own, .shared:
            break
        }
        if isUpscalingVideo {
            return upscalingIsImage ? String(localized: "画像を拡大しています。終わってから生成してください")
                                    : String(localized: "動画を拡大しています。終わってから生成してください")
        }
        if promptIsEmpty {
            return imageEditReferences.isEmpty ? String(localized: "画像の内容を入力してください")
                                               : String(localized: "参照画像をどう変えるかを入力してください")
        }
        if !imageEditReferences.isEmpty && !imageModelCanEdit {
            return String(localized: "画像モデル「\(model.name)」は、まだ画像の編集（参照画像）に対応していません。参照画像を外してください")
        }
        if imageEditReferences.count > imageReferenceLimit {
            return String(localized: "参照画像は\(imageReferenceLimit)枚までです")
        }
        if let missing = imageEditReferences.first(where: { !FileManager.default.fileExists(atPath: $0) }) {
            return String(localized: "参照画像が見つかりません: \(URL(fileURLWithPath: missing).lastPathComponent)")
        }
        if let plan = currentImagePlan, plan.verdict == .tooLarge {
            return plan.textTokens > plan.textTokenLimit
                ? String(localized: "参照画像が多すぎて生成できません。参照の数を減らしてください")
                : String(localized: "このMacのメモリでは生成できない大きさです。参照の数を減らすか、サイズを下げてください")
        }
        if imageSeedFixed && UInt64(imageSeedText) == nil {
            return imageSeedText.isEmpty ? String(localized: "シード値を入力してください")
                                         : String(localized: "シード値は0〜18446744073709551615の整数にしてください")
        }
        return nil
    }

    // MARK: What an edit will take

    /// The image engine of the active image model, made when first needed
    /// (it only looks at the folder); nil when the folder is not a model.
    func activeImageEngine() -> H3ImageEngine? {
        guard let model = library.activeImageModel else { return nil }
        return try? imageEngine(for: model)
    }

    /// The registered video models, the one in use first: where an image
    /// model without a text encoder of its own reads one (SharedTextEncoder).
    var videoModelPaths: [String] {
        ([library.activeModel].compactMap { $0 } + library.models).map(\.path)
    }

    /// The engine for an image model folder: the one made last, while the
    /// folder and the text encoder it reads are the same.
    func imageEngine(for model: H3ModelEntry) throws -> H3ImageEngine {
        let textEncoder = SharedTextEncoder.directory(forImageModel: model.path, videoModelPaths: videoModelPaths)
        if let current = imageEngine, current.modelDirectory == model.path,
           current.textEncoderDirectory == textEncoder {
            return current
        }
        let engine = try H3ImageEngine(modelDirectory: model.path, textEncoderDirectory: textEncoder)
        imageEngine = engine
        return engine
    }

    /// The request the form would generate, without its seed.
    private func imagePlanParams() -> H3ImageParams {
        let size = imageSizeProfile.dimensions
        return H3ImageParams(prompt: imagePrompt.trimmingCharacters(in: .whitespacesAndNewlines),
                             width: size.width, height: size.height, seed: 0,
                             references: imageEditReferences.map { H3ImageReference(path: $0) },
                             referenceMaxShortEdge: Int32(preferences.imageReferenceShortEdge))
    }

    /// Everything the plan depends on, as CreationFormView's .task(id:);
    /// nil when there is nothing to plan: an image from the prompt alone
    /// (its memory does not depend on the request enough to matter), or no
    /// image model.
    var imagePlanKey: String? {
        guard generationKind == .image, !imageEditReferences.isEmpty,
              let model = library.activeImageModel else { return nil }
        let params = imagePlanParams()
        return ([model.path, params.prompt, "\(params.width)x\(params.height)", "\(params.referenceMaxShortEdge)"]
                + imageEditReferences).joined(separator: "\n")
    }

    /// The plan while it still describes the form, else nil.
    var currentImagePlan: H3GenerationPlan? {
        guard let key = imagePlanKey, key == imagePlanInputs else { return nil }
        return imagePlan
    }

    /// Plans the image form's edit off the main thread; waits a moment
    /// first, so typing a prompt does not plan every key.
    func refreshImagePlan() async {
        guard let key = imagePlanKey, key != imagePlanInputs else { return }
        try? await Task.sleep(nanoseconds: 300_000_000)
        if Task.isCancelled { return }
        guard let engine = activeImageEngine() else { return }
        let params = imagePlanParams()
        let plan = await Task.detached(priority: .userInitiated) { engine.plan(params) }.value
        if Task.isCancelled || imagePlanKey != key { return }
        imagePlan = plan
        imagePlanInputs = key
    }

    /// Whether the image model in use takes reference images: P-H3-Image
    /// does not yet.
    var imageModelCanEdit: Bool { activeImageEngine()?.canEdit ?? true }

    /// As many references as the image model in use takes.
    var imageReferenceLimit: Int { activeImageEngine()?.referenceLimit ?? H3ImageEngine.maxReferences }

    /// Whether the image model in use is P-H3-Image (its own edit sizes).
    var imageModelIsPH3: Bool { activeImageEngine()?.isPH3 ?? false }

    var canGenerateImage: Bool {
        !isGenerating && !isBuildingCache && !isImportingImages && !isImportingVideo && !isMovingProjectFiles
            && imageValidationMessage == nil
    }

    // MARK: Image models

    /// 画像モデルのフォルダを追加…: a folder holding transformer/, vae/,
    /// text_encoder/ and tokenizer/ (include/h3_image.h). Checked before it
    /// is listed.
    func chooseAndAddImageModel() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.allowsMultipleSelection = false
        panel.message = String(localized: "画像モデルのフォルダ（transformer・vae・text_encoder・tokenizer を含むもの）を選んでください")
        guard panel.runModal() == .OK, let url = panel.url else { return }
        addImageModel(at: url.path)
    }

    /// Returns why the folder is not an image model, or nil once it is listed.
    @discardableResult
    func addImageModel(at path: String, name: String? = nil) -> String? {
        if let existing = library.imageModels.first(where: { $0.path == path }) {
            library.selectImageModel(id: existing.id)
            return nil
        }
        do {
            _ = try H3ImageEngine(modelDirectory: path, textEncoderDirectory: SharedTextEncoder.directory(
                forImageModel: path, videoModelPaths: videoModelPaths))
        } catch {
            let reason = String(localized: "画像モデルとして使えません（詳細: \(error.localizedDescription)）")
            projectMessage = reason
            return reason
        }
        library.addImageModel(path: path, name: name)
        if let added = library.imageModels.last { library.selectImageModel(id: added.id) }
        return nil
    }

    // MARK: Generating

    /// The composer's generate action on the image side: `imageCount`
    /// images one after another into the project (an untitled one is
    /// started when none is open), each with its record and latent. The
    /// first uses the fixed seed, if one is set; the rest draw their own.
    func generateImages() {
        guard canGenerateImage, let model = library.activeImageModel else { return }
        if project == nil { startUntitledProject() }
        guard let project else { return }
        // The plan describes the form as it was planned: a change since
        // (the copies below rename the references) is planned by the
        // engine itself, which refuses what cannot fit.
        // An edit's pictures are copied into the project first (in the
        // background), so the record names files inside it.
        saveProjectIfChanged(importingReferences: !imageEditReferences.isEmpty)
        if let copying = referenceImportTask {
            imageReferenceCopyBegan()
            Task {
                await copying.value
                if !self.imageReferenceCopyEnded() { self.generateImages() }
            }
            return
        }
        let engine: H3ImageEngine
        do {
            engine = try imageEngine(for: model)
        } catch {
            errorMessage = Self.userFacingMessage(for: error)
            return
        }
        var draft = currentImageDraft() ?? .blank
        draft.model = model.id.uuidString
        let total = imageCount.clamped(to: imageCountRange)
        let size = imageSizeProfile.dimensions
        let fixedSeed = imageSeedFixed ? UInt64(imageSeedText) : nil
        let prompt = imagePrompt.trimmingCharacters(in: .whitespacesAndNewlines)
        let projectURL = project.url
        let installed = H3ImageModel.installed(at: model.path)
        let shortEdge = imageReferenceShortEdgeOverride ?? preferences.imageReferenceShortEdge
        let useLatents = imageReferenceLatentsOverride ?? preferences.useImageLatentsForEdits
        imageReferenceShortEdgeOverride = nil
        imageReferenceLatentsOverride = nil
        let references = imageEditReferences.map { path in
            H3ImageReference(path: path, latentPath: useLatents
                ? Self.editLatent(forReference: path, maxShortEdge: shortEdge, ph3: engine.isPH3) : nil)
        }
        let request = ImageStoreRequest(
            projectURL: projectURL, draft: draft, references: imageEditReferences, modelName: model.name,
            systemName: engine.modelName, modelSource: installed?.weightsRepo,
            modelRevision: installed?.weightsRevision,
            deviceLine: engineState == .ready ? deviceLine : nil, appVersion: Self.appVersion,
            recordsPrompt: GenerationMetadata.exportsSettings)
        imageBatchStopped = false
        displayedImage = nil
        // Now, not in the task: whoever asked sees a generation running.
        imageGenerationBegan(index: 1, total: total)
        imageGenerationTask = Task {
            for index in 1 ... total {
                let seed = index == 1 ? (fixedSeed ?? UInt64.random(in: UInt64.min ... UInt64.max))
                                      : UInt64.random(in: UInt64.min ... UInt64.max)
                let startedAt = Date()
                if index > 1 { self.imageGenerationBegan(index: index, total: total) }
                var finished: H3ImageResult?
                do {
                    let params = H3ImageParams(prompt: prompt, width: size.width, height: size.height, seed: seed,
                                               references: references, referenceMaxShortEdge: Int32(shortEdge),
                                               latentPreview: self.preferences.showImageDenoisePreview)
                    for try await event in engine.generate(params) {
                        switch event {
                        case .progress(let phase, let completed, let total):
                            self.imageGenerationProgress(phase: phase, completed: completed, total: total)
                        case .latentPreview(let preview):
                            self.showImageLatentPreview(preview, isPH3: engine.isPH3)
                        case .finished(let result):
                            finished = result
                        }
                    }
                } catch {
                    if case H3EngineError.cancelled = error {
                        self.phase = String(localized: "生成を中止しました")
                    } else {
                        self.errorMessage = Self.userFacingMessage(for: error)
                    }
                }
                guard let result = finished else { break }
                let seconds = Date().timeIntervalSince(startedAt)
                let stored = await Task.detached(priority: .userInitiated) {
                    Result { try request.store(result, seedWasRandom: index > 1 || fixedSeed == nil,
                                               completedAt: Date(), generationSeconds: seconds) }
                }.value
                switch stored {
                case .success(let image):
                    if self.project?.url == projectURL {
                        self.reloadProjectImages()
                        self.displayedImage = self.projectImages.first { $0.url == image.url } ?? image
                        self.resultURL = nil
                        self.lastResult = nil
                    }
                case .failure(let error):
                    self.errorMessage = String(localized: "画像を保存できませんでした（詳細: \(error.localizedDescription)）")
                }
                if self.imageBatchStopped { break }
                if case .failure = stored { break }
            }
            self.imageGenerationEnded()
            self.imageGenerationTask = nil
        }
    }

    var imageDraftSummaryText: String {
        var parts = [imageSizeProfile.label, String(localized: "\(imageCount)枚")]
        if !imageEditReferences.isEmpty { parts.append(String(localized: "参照\(imageEditReferences.count)枚を編集")) }
        if imageSizeProfile.isVideoCanvas { parts.append(String(localized: "動画の開始画像用")) }
        if imageSeedFixed { parts.append(String(localized: "シード固定")) }
        if let model = library.activeImageModel { parts.append(model.name) }
        return parts.joined(separator: summarySeparator)
    }

    // MARK: The project's images

    func reloadProjectImages() {
        projectImages = project.map { ProjectFiles.images(in: $0.url) } ?? []
        // The image in the preview (this project's, or another's shown from
        // すべてのプロジェクト) may have been moved or deleted.
        if let displayed = displayedImage {
            displayedImage = projectImages.first { $0.url == displayed.url }
                ?? (FileManager.default.fileExists(atPath: displayed.url.path) ? displayed : nil)
        }
    }

    /// 画像を取り込む…: image files become images of the project, as PNG,
    /// each with a record saying where it came from. They are not marked as
    /// AI-generated here: the app did not make them. What a file says of its
    /// own origin stays in it.
    func chooseAndImportImages() {
        let paths = chooseFiles(allowedContentTypes: imageTypes)
        guard !paths.isEmpty else { return }
        importImages(from: paths.map { URL(fileURLWithPath: $0) })
    }

    func importImages(from sources: [URL]) {
        guard !isImportingImages else { return }
        if project == nil { startUntitledProject() }
        guard let project else { return }
        let projectURL = project.url
        let appVersion = Self.appVersion
        isImportingImages = true
        Task { [weak self] in
            let results = await Task.detached(priority: .userInitiated) { () -> [Result<ProjectImage, Error>] in
                sources.map { source in
                    Result {
                        guard let image = ImageMetadata.pngForImport(at: source) else {
                            throw ProjectImageError.unreadable(source.lastPathComponent)
                        }
                        let now = Date()
                        return try ProjectFiles.storeImage(
                            png: image.png, latent: nil, completedAt: now, seed: nil, into: projectURL
                        ) { name, sha256 in
                            ProjectImageRecord(assetID: UUID().uuidString, image: name, sha256: sha256,
                                               completedAt: now, width: image.width, height: image.height,
                                               appVersion: appVersion, importedFrom: source.lastPathComponent)
                        }
                    }
                }
            }.value
            guard let self else { return }
            self.isImportingImages = false
            var imported: [ProjectImage] = []
            var failure: Error?
            for result in results {
                switch result {
                case .success(let image): imported.append(image)
                case .failure(let error): failure = error
                }
            }
            if let failure {
                self.projectMessage = String(localized: "画像を取り込めませんでした（詳細: \(failure.localizedDescription)）")
            }
            guard self.project?.url == projectURL else { return }
            self.reloadProjectImages()
            // The last one brought in goes to the preview.
            if let last = imported.last, let image = self.projectImages.first(where: { $0.url == last.url }) {
                self.showProjectImage(image)
            }
        }
    }

    // MARK: Preview

    /// Shows a project image in the preview, in place of a video.
    func showProjectImage(_ image: ProjectImage) {
        guard !isGenerating else { return }
        deleteTemporaryPreview()
        resultURL = nil
        lastResult = nil
        displayedImage = image
    }

    /// Puts an image's request back into the image form with its seed
    /// pinned. An image brought in from a file has none.
    func restoreProjectImage(_ image: ProjectImage) {
        guard var draft = image.record?.draft else { return }
        if let seed = image.record?.seed {
            draft.seedFixed = true
            draft.seed = seed
        }
        generationKind = .image
        // An edit's pictures are named relative to the project the image is
        // in (images/ is its folder). The record is a file anyone could
        // have written: its paths are taken only from inside that project.
        let folder = image.url.deletingLastPathComponent().deletingLastPathComponent()
        noteInputsNamedOnDisk((draft.references ?? []).map { ProjectFiles.resolved($0, in: folder) },
                              for: folder, keeping: formInputPaths)
        applyImageDraft(draft, projectURL: folder)
    }

    /// Moves the image, its record, latent and thumbnail to the Trash.
    func deleteProjectImage(_ image: ProjectImage) {
        do {
            try FileManager.default.trashItem(at: image.url, resultingItemURL: nil)
            for url in [ProjectFiles.imageRecordURL(for: image.url), ProjectFiles.imageLatentURL(for: image.url)]
            where FileManager.default.fileExists(atPath: url.path) {
                try FileManager.default.trashItem(at: url, resultingItemURL: nil)
            }
            // A cache, made again when needed: just removed.
            try? FileManager.default.removeItem(at: ProjectFiles.imageThumbnailURL(for: image.url))
            if displayedImage?.url == image.url { displayedImage = nil }
        } catch {
            projectMessage = String(localized: "画像を削除できませんでした（詳細: \(error.localizedDescription)）")
        }
        reloadProjectImages()
    }

    /// 別のプロジェクトに移動: the image, its record and latent go to the
    /// project at `destination`. Returns nil when done, else why not. A
    /// video made from it keeps its own copy in references/.
    func moveProjectImage(_ image: ProjectImage, to destination: URL) async -> String? {
        guard let project else { return String(localized: "プロジェクトが開いていません。") }
        if let busy = projectFilesBusyReason { return busy }
        let target = destination.standardizedFileURL
        guard target.path != project.url.standardizedFileURL.path else {
            return String(localized: "移動先が今のプロジェクトです。ほかのプロジェクトを選んでください。")
        }
        guard (try? ProjectFiles.read(target)) != nil else {
            return ProjectError.notAProject(target.path).localizedDescription
        }
        guard FileManager.default.fileExists(atPath: image.url.path) else {
            return String(localized: "画像が見つかりません: \(image.url.lastPathComponent)")
        }
        isMovingProjectFiles = true
        defer { isMovingProjectFiles = false }
        let source = image.url
        let result = await Task.detached(priority: .userInitiated) {
            Result { try ProjectFiles.moveImage(source, to: target) }
        }.value
        switch result {
        case .failure(let error):
            reloadProjectImages()
            return String(localized: "画像を移動できませんでした（詳細: \(error.localizedDescription)）")
        case .success(let moved):
            if displayedImage?.url == source { displayedImage = nil }
            reloadProjectImages()
            ProjectStore.shared.owner(of: target)?.reloadProjectImages()
            let projectName = (try? ProjectFiles.read(target).name) ?? target.lastPathComponent
            projectMessage = String(localized: "\(source.lastPathComponent)を「\(projectName)」に移動しました（\(moved.lastPathComponent)）")
            projectMessageFile = moved
            return nil
        }
    }

    // MARK: Handing an image to the video form

    /// この画像から動画を作る: the video form starts from this image. The
    /// image's prompt goes into an empty video prompt. Nothing is generated.
    func makeVideo(from image: ProjectImage) {
        let path = image.url.path
        noteInputsChosen([path])
        generationKind = .video
        creationMethod = .image
        imageInputMode = .firstLastFrame
        firstFramePath = path
        // The prompt this image was made from; one brought in has none.
        if prompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
           let made = image.record?.prompt, !made.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            prompt = made
        }
    }

    /// 最後の画像に使う: the video form ends on this image.
    func useImageAsLastFrame(_ image: ProjectImage) {
        let path = image.url.path
        noteInputsChosen([path])
        generationKind = .video
        creationMethod = .image
        imageInputMode = .firstLastFrame
        lastFramePath = path
    }

    /// 参照画像に追加: the video form takes this image as a reference. That
    /// mode needs the model's Ref2VA; returns false when the active model
    /// has none (the image is added all the same, for when it does).
    @discardableResult
    func addImageAsReference(_ image: ProjectImage) -> Bool {
        let path = image.url.path
        noteInputsChosen([path])
        generationKind = .video
        creationMethod = .image
        imageInputMode = .referenceImage
        if !referenceImages.contains(where: { $0.path == path }) {
            referenceImages.append(H3ReferenceInput(kind: .image, path: path))
        }
        return library.activeModel.map(modelHasRef2VA) ?? true
    }
}

/// What storing a generated image needs, taken on the main actor so the
/// encoding and writing can run off it.
struct ImageStoreRequest: Sendable {
    let projectURL: URL
    let draft: ImageDraft
    /// The pictures of an edit, as the engine was given them (absolute).
    var references: [String] = []
    let modelName: String
    /// Which image model it is (h3_image_get_info): "MiniMax H3 Image" or
    /// "P-H3-Image", written into the PNG as the AI system used.
    let systemName: String
    /// The repository and revision of a model the app installed itself.
    let modelSource: String?
    let modelRevision: String?
    let deviceLine: String?
    let appVersion: String
    /// Whether the PNG's own metadata carries the prompt (the record
    /// always does), as for a video (GenerationMetadata.exportsSettings).
    let recordsPrompt: Bool
    /// A redraw (高解像度化): what it was made from, recorded.
    var upscale: UpscaleNote? = nil

    struct UpscaleNote: Sendable {
        let from: String
        let method: String
        let factor: Double
        let strength: Double?
    }

    /// The latent as a safetensors file: "latent" F32 [24, height, width].
    static func latentFile(_ result: H3ImageResult) -> Data {
        let bytes = result.latent.count * MemoryLayout<Float>.size
        var header = "{\"__metadata__\":{\"latent_space\":\"\(imageLatentSpaceID)\",\"normalization\":\"\(imageLatentNormalization)\"},"
            + "\"latent\":{\"dtype\":\"F32\",\"shape\":[24,\(result.latentHeight),\(result.latentWidth)],\"data_offsets\":[0,\(bytes)]}}"
        while header.utf8.count % 8 != 0 { header += " " }
        var data = Data()
        withUnsafeBytes(of: UInt64(header.utf8.count).littleEndian) { data.append(contentsOf: $0) }
        data.append(contentsOf: header.utf8)
        result.latent.withUnsafeBufferPointer { data.append(UnsafeBufferPointer(rebasing: $0[...])) }
        return data
    }

    /// Encodes the PNG (marked as AI-generated) and writes it with its
    /// record and latent into the project's images.
    func store(_ result: H3ImageResult, seedWasRandom: Bool, completedAt: Date,
               generationSeconds: Double) throws -> ProjectImage {
        guard let provider = CGDataProvider(data: result.rgb as CFData),
              let image = CGImage(width: result.width, height: result.height, bitsPerComponent: 8,
                                  bitsPerPixel: 24, bytesPerRow: result.width * 3,
                                  space: CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB(),
                                  bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.none.rawValue),
                                  provider: provider, decode: nil, shouldInterpolate: false,
                                  intent: .defaultIntent),
              let png = ImageMetadata.pngData(image, disclosure: .init(
                  creatorTool: "H3cApp \(appVersion)", createdAt: completedAt,
                  system: systemName, systemVersion: modelName,
                  prompt: recordsPrompt ? draft.prompt : nil))
        else { throw ProjectImageError.cannotEncode }
        var pinned = draft
        pinned.seedFixed = true
        pinned.seed = String(result.seed)
        pinned.count = 1
        let latent = ProjectImageRecord.Latent(
            file: "", width: result.latentWidth, height: result.latentHeight, channels: 24,
            spaceID: imageLatentSpaceID, normalization: imageLatentNormalization, dtype: "F32", layout: "CHW")
        // What the edit was made from: each picture's file, hash and the
        // project image it is (or is a copy of), and how it was used.
        let used: [ProjectImageRecord.Reference] = references.enumerated().map { index, path in
            let use = index < result.references.count ? result.references[index] : nil
            return ProjectImageRecord.Reference(
                file: ProjectFiles.stored(path, in: projectURL),
                sha256: try? FileHash.sha256(ofFile: path),
                sourceImage: ProjectFiles.sourceImageID(forFrame: path),
                width: use?.width ?? 0, height: use?.height ?? 0, usedLatent: use?.fromLatent)
        }
        return try ProjectFiles.storeImage(
            png: png, latent: (Self.latentFile(result), latent), completedAt: completedAt,
            seed: result.seed, into: projectURL
        ) { name, sha256 in
            var record = ProjectImageRecord(
                assetID: UUID().uuidString, image: name, sha256: sha256, completedAt: completedAt,
                width: result.width, height: result.height, appVersion: appVersion, draft: pinned,
                model: .init(name: modelName, source: modelSource, revision: modelRevision),
                seed: String(result.seed), seedWasRandom: seedWasRandom,
                steps: result.steps, sigmas: result.sigmas.map(Double.init),
                generationSeconds: generationSeconds, deviceLine: deviceLine)
            if !used.isEmpty {
                record.references = used
                record.referenceSeconds = result.referenceSeconds
            }
            if let upscale {
                record.upscaledFrom = upscale.from
                record.upscaler = upscale.method
                record.upscaleFactor = upscale.factor
                record.upscaleStrength = upscale.strength
            }
            return record
        }
    }
}

/// The latent space the image model works in: the H3 VAE's 24 channels at
/// 1/16 of the pixels (its encoder is the video VAE's own), stored with the
/// VAE's latents_mean / latents_std taken out.
let imageLatentSpaceID = "minimax-h3-vae-24ch-16x"
let imageLatentNormalization = "latents_mean_std"
